// === Validação de assinatura HMAC-SHA256 do Square (tempo constante) ===
// string_to_sign = notification_url EXATA registrada no Square + RAW body
// hmac = Base64( HMAC_SHA256(signature_key, string_to_sign) )
// Compara com o header x-square-hmacsha256-signature.
const crypto = require('crypto');

const item = $input.first();
const headers = item.json.headers || {};

// --- 1) Recuperar o RAW body (NUNCA usar o JSON já parseado para o HMAC) ---
// Com 'Raw Body' ligado no Webhook, o corpo cru vem em binary.data (base64).
let rawBody;
if (item.binary && item.binary.data && item.binary.data.data) {
  rawBody = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
} else {
  // Fallback (pode divergir dos bytes originais — apenas última instância).
  rawBody = JSON.stringify(item.json.body);
}

// --- 2) Segredos e URL via variáveis de ambiente (NUNCA hardcoded) ---
const signatureKey = $env.SQUARE_SIGNATURE_KEY;
// URL EXATA registrada no Square Developer Dashboard, ex.:
// https://n8n.seudominio.com/webhook/square-payment
const notificationUrl = $env.SQUARE_NOTIFICATION_URL;

if (!signatureKey || !notificationUrl) {
  throw new Error('Faltam variáveis de ambiente SQUARE_SIGNATURE_KEY e/ou SQUARE_NOTIFICATION_URL.');
}

// --- 3) Calcular HMAC e comparar em tempo constante ---
const received = headers['x-square-hmacsha256-signature'] || '';
const expected = crypto
  .createHmac('sha256', signatureKey)
  .update(notificationUrl + rawBody)
  .digest('base64');

let valid = false;
try {
  const a = Buffer.from(expected);
  const b = Buffer.from(received);
  valid = a.length === b.length && crypto.timingSafeEqual(a, b);
} catch (e) {
  valid = false;
}

// IMPORTANTE: não devolvemos o body completo em log. Passamos adiante para os filtros.
return [{ json: { valid, body: item.json.body } }];

// Normaliza o payload para um formato plano usado pelo resto do fluxo.
const body = $json.body;
const payment = body.data.object.payment;
return [{
  json: {
    event_id: body.event_id,
    payment,
    email: payment.buyer_email_address || null,
    phone: null // telefone não vem no objeto payment; será buscado no enriquecimento se necessário
  }
}];

// Consolida e-mail/telefone a partir do enriquecimento.
// Ordem de preferência: customer > payment.
const norm = $('Normalizar payload').item.json;
const pay = $('Square API: GET payment').item.json.payment || norm.payment;

let customer = null;
try { customer = $('Square API: GET customer').item.json.customer || null; } catch (e) { customer = null; }

const email = (customer && customer.email_address) || pay.buyer_email_address || null;
const phone = (customer && customer.phone_number) || null;

return [{
  json: {
    event_id: norm.event_id,
    payment: pay,
    email,
    phone
  }
}];

// Monta o JSON limpo enviado ao Inbound Webhook do GHL.
const src = $json; // { event_id, payment, email, phone }
const p = src.payment;

// amount vem em CENTAVOS no Square -> dividir por 100.
const amount = (Number(p.amount_money.amount) / 100).toFixed(2);

return [{
  json: {
    event: 'square_payment_completed',
    payment_status: 'COMPLETED',
    payment_provider: 'Square',
    payment_id: p.id,
    order_id: p.order_id || null,
    amount,                                   // ex.: "199.00"
    currency: p.amount_money.currency,
    receipt_url: p.receipt_url || null,
    email: src.email,                         // chave de match no GHL
    phone: src.phone,                         // fallback de match
    paid_at: p.updated_at || p.created_at,
    last_square_event_id: src.event_id
  }
}];
